 static void RestoreBoundsSafe(Form w,int x,int y,int width,int height){if(x<0&&y<0)return;var rect=new Rectangle(x,y,Math.Max(w.MinimumSize.Width,Math.Min(2400,width)),Math.Max(w.MinimumSize.Height,Math.Min(1600,height)));if(Screen.AllScreens.Any(s=>Rectangle.Intersect(s.WorkingArea,rect).Width>=150&&Rectangle.Intersect(s.WorkingArea,rect).Height>=100)){w.StartPosition=FormStartPosition.Manual;w.Bounds=rect;}}
 void TrimHistory(){if(preferences.Retention<=0)return;DateTime threshold=DateTime.Now.AddDays(-preferences.Retention);alerts.RemoveAll(a=>!a.Demo&&!RecentAlert(a,threshold));}
 static bool RecentAlert(Alert a,DateTime threshold){DateTime time;return DateTime.TryParse(a.Time,out time)&&time>=threshold;}
 void SaveExperience(){if(!experienceReady)return;try{var r=WindowState==FormWindowState.Normal?Bounds:RestoreBounds;preferences.X=r.X;preferences.Y=r.Y;preferences.Width=r.Width;preferences.Height=r.Height;preferences.Sound=sound.Checked;preferences.Popup=desktop.Checked;preferences.Top=TopMost;preferences.Filter=filter.SelectedIndex;preferences.Search=search.Text;if(alertsWindow!=null)CapturePopout(alertsWindow);string settingsJson=ExperienceJson.Serialize(preferences);if(settingsJson!=lastSavedPreferences){WriteProtected("preferences.bin",settingsJson);lastSavedPreferences=settingsJson;}int before=alerts.Count;TrimHistory();if(alerts.Count!=before){historyDirty=true;RefreshFeed();}if(historyDirty){WriteProtected("history.bin",ExperienceJson.Serialize(preferences.Retention==0?new List<Alert>():alerts.Where(a=>!a.Demo).Take(2000).ToList()));historyDirty=false;}storageError="";}catch{storageError="Settings or history could not be saved. Check available disk space.";}}
 void RecordArrival(Alert a){if(!a.Demo){lastEvents[a.Platform]=DateTime.Now;historyDirty=true;}}
 void CapturePopout(Form w){var r=w.WindowState==FormWindowState.Normal?w.Bounds:w.RestoreBounds;preferences.PopX=r.X;preferences.PopY=r.Y;preferences.PopWidth=r.Width;preferences.PopHeight=r.Height;preferences.PopTop=w.TopMost;}
 void SetupPopout(Form w,CheckBox pin){RestoreBoundsSafe(w,preferences.PopX,preferences.PopY,preferences.PopWidth,preferences.PopHeight);pin.Checked=preferences.PopTop;preferences.PopOpen=true;w.MinimumSize=new Size(preferences.Compact?500:760,260);w.FormClosing+=delegate{CapturePopout(w);if(!closingExperience)preferences.PopOpen=false;};}
 void ApplyCompact(){if(feed.Columns.Count<5)return;if(alertsWindow!=null)alertsWindow.MinimumSize=new Size(preferences.Compact?500:760,260);if(preferences.Compact){if(feed.Font.Size!=12){var old=feed.Font;feed.Font=new Font("Segoe UI",12);old.Dispose();}feed.Columns[0].Width=0;feed.Columns[1].Width=0;feed.Columns[2].Width=160;feed.Columns[3].Width=150;feed.Columns[4].Width=Math.Max(180,feed.ClientSize.Width-315);}else{if(feed.Font.Size!=11){var old=feed.Font;feed.Font=new Font("Segoe UI",11);old.Dispose();}int width=feed.ClientSize.Width;feed.Columns[0].Width=78;feed.Columns[1].Width=92;feed.Columns[2].Width=185;feed.Columns[3].Width=120;feed.Columns[4].Width=Math.Max(170,width-479);}}
 void PlayEventSound(Alert alert){var rule=EventRule(alert.Kind);if(!sound.Checked||!rule.Sound||rule.Volume<=0||DateTime.UtcNow<pausedUntil||(DateTime.UtcNow-lastSound).TotalSeconds<1)return;lastSound=DateTime.UtcNow;string path=string.IsNullOrEmpty(rule.File)?SoundPreferences.Read():rule.File;try{if(!File.Exists(path))path=SoundPreferences.DefaultPath;eventPlayer.Stop();eventPlayer.Open(new Uri(Path.GetFullPath(path)));eventPlayer.Volume=Math.Max(0,Math.Min(100,rule.Volume))/100.0;eventPlayer.Play();audioError="";}catch{audioError="Notification sound unavailable. Choose another WAV file.";}}
 bool ShowEventPopup(Alert a){return desktop.Checked&&EventRule(a.Kind).Popup;}
 void ShowExperience(){using(var w=new Form{Text="Alert preferences",Size=new Size(800,690),MinimumSize=new Size(760,600),StartPosition=FormStartPosition.CenterParent,BackColor=Theme.Canvas,ForeColor=Theme.Text,Font=Font}){
 var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(20)};w.Controls.Add(panel);
