 void ShowConnectionHealth(){using(var w=new Form{Text="Connection health",Size=new Size(790,430),StartPosition=FormStartPosition.CenterParent,BackColor=Theme.Canvas,ForeColor=Theme.Text,Font=Font}){var text=new Label{Dock=DockStyle.Fill,Padding=new Padding(24)};w.Controls.Add(text);Action refresh=delegate{text.Text=string.Join("\n\n",new[]{"Twitch","YouTube","Kick","Streamlabs"}.Select(name=>{DateTime last;string value=name=="Twitch"?twitchStatus:name=="YouTube"?youtubeStatus:name=="Kick"?kickStatus:streamlabsStatus;return value+"\nLast received event: "+(lastEvents.TryGetValue(name,out last)?last.ToString("g"):"None yet");}));};refresh();var timer=new System.Windows.Forms.Timer{Interval=1000};timer.Tick+=delegate{refresh();};timer.Start();try{w.ShowDialog(this);}finally{timer.Dispose();}}}
